        ci = &local;
        ci->usage = SDL_GPU_TRANSFERBUFFERUSAGE_DOWNLOAD;
        ci->size = (uint32_t)n;
        d->down_tb = SDL_CreateGPUTransferBuffer(d->dev, ci);
        d->down_cap = d->down_tb != NULL ? (uint32_t)n : 0;
        if (d->down_tb == NULL) {
            sdl_fail("SDL_CreateGPUTransferBuffer");
            return false;
        }
